// pp:data-source auto

// newNovelAnalyticsCmd implements fleet-wide analytics over the local SQLite
// mirror. Four report types, each a cross-entity aggregation no single Zapmail
// API call returns: fleet-health (domain deliverability rollup), renewals
// (forward cost forecast), cost-efficiency (spend per assigned mailbox), and
// capacity (purchased vs assigned vs available).
func newNovelAnalyticsCmd(flags *rootFlags) *cobra.Command {
	var flagType string
	var flagGroupBy string
	var flagDBPath string
	var flagUnhealthyBelow int

	cmd := &cobra.Command{
		Use:   "analytics",
		Short: "Fleet analytics over the local store: fleet-health, renewals, cost-efficiency, capacity",
		Long: strings.Trim(`
Cross-entity analytics computed from the local SQLite mirror. Run 'sync' first.

Report types (--type):
  fleet-health     Domain deliverability rollup: health scores + abused flags, worst first
  renewals         Upcoming subscription renewals bucketed by week with summed cost
  cost-efficiency  Active subscription spend divided by assigned mailboxes
  capacity         Purchased vs assigned vs available mailbox capacity

These read only synced data. None of them maps to a single Zapmail endpoint.
`, "\n"),
		Example: strings.Trim(`
  zapmail-pp-cli analytics --type fleet-health --group-by workspace
  zapmail-pp-cli analytics --type renewals --group-by week --json
  zapmail-pp-cli analytics --type cost-efficiency --json
  zapmail-pp-cli analytics --type capacity --json
`, "\n"),
		Annotations: map[string]string{"mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if flagType == "" {
				return fmt.Errorf("--type is required: one of fleet-health, renewals, cost-efficiency, capacity")
			}
			if dryRunOK(flags) {
				return nil
			}
			dbPath := flagDBPath
			if dbPath == "" {
				dbPath = defaultDBPath("zapmail-pp-cli")
			}
			db, err := store.OpenWithContext(cmd.Context(), dbPath)
			if err != nil {
				return fmt.Errorf("opening local store: %w", err)
			}
			defer db.Close()

			switch strings.ToLower(flagType) {
			case "fleet-health":
				return analyticsFleetHealth(cmd, db, flags, flagUnhealthyBelow)
			case "renewals":
				return analyticsRenewals(cmd, db, flags)
			case "cost-efficiency", "cost-per-mailbox":
				return analyticsCostEfficiency(cmd, db, flags)
			case "capacity":
				return analyticsCapacity(cmd, db, flags)
			default:
				return fmt.Errorf("unknown --type %q: choose fleet-health, renewals, cost-efficiency, or capacity", flagType)
			}
		},
	}
	cmd.Flags().StringVar(&flagType, "type", "", "Report type: fleet-health | renewals | cost-efficiency | capacity")
	cmd.Flags().StringVar(&flagGroupBy, "group-by", "workspace", "Grouping dimension (v1 syncs one workspace, so this is informational)")
	cmd.Flags().StringVar(&flagDBPath, "db", "", "Database path (defaults to the standard local store)")
	cmd.Flags().IntVar(&flagUnhealthyBelow, "unhealthy-below", 70, "Health score below this counts a domain as unhealthy")
	return cmd
}

type fleetHealthRow struct {
	Domain       string `json:"domain"`
	Status       string `json:"status"`
	AverageScore int    `json:"averageScore"`
	IsAbused     bool   `json:"isAbused"`
	Healthy      bool   `json:"healthy"`
}

func analyticsFleetHealth(cmd *cobra.Command, db *store.Store, flags *rootFlags, unhealthyBelow int) error {
	if !hintIfUnsynced(cmd, db, "domains") {
		hintIfStale(cmd, db, "domains", flags.maxAge)
	}
	rows, err := db.Query(`SELECT COALESCE(domain,''), COALESCE(status,''), COALESCE(average_score,0), COALESCE(is_abused,0) FROM "domains" ORDER BY average_score ASC, domain ASC`)
	if err != nil {
		return fmt.Errorf("querying domains: %w", err)
	}
	defer rows.Close()

	out := []fleetHealthRow{}
	var unhealthy, abused int
	for rows.Next() {
		var r fleetHealthRow
		var abusedInt int
		if err := rows.Scan(&r.Domain, &r.Status, &r.AverageScore, &abusedInt); err != nil {
			return fmt.Errorf("scanning domain: %w", err)
		}
		r.IsAbused = abusedInt != 0
		r.Healthy = r.AverageScore >= unhealthyBelow && !r.IsAbused
		if !r.Healthy {
			unhealthy++
		}
		if r.IsAbused {
			abused++
		}
		out = append(out, r)
	}
	if err := rows.Err(); err != nil {
		return err
	}
	fmt.Fprintf(cmd.ErrOrStderr(), "fleet-health: %d domains, %d unhealthy (score < %d or abused), %d abused\n", len(out), unhealthy, unhealthyBelow, abused)
	return printJSONFiltered(cmd.OutOrStdout(), out, flags)
}

type renewalRow struct {
	Plan      string  `json:"plan"`
	Status    string  `json:"status"`
	Price     float64 `json:"price"`
	PeriodEnd string  `json:"periodEnd"`
	WeeksOut  int     `json:"weeksOut"`
	Bucket    string  `json:"bucket"`
}

func analyticsRenewals(cmd *cobra.Command, db *store.Store, flags *rootFlags) error {
	if !hintIfUnsynced(cmd, db, "subscriptions") {
		hintIfStale(cmd, db, "subscriptions", flags.maxAge)
	}
	rows, err := db.Query(`SELECT COALESCE(plan,''), COALESCE(subscription_status,''), COALESCE(price,0), COALESCE(period_end,'') FROM "subscriptions" WHERE period_end != '' ORDER BY period_end ASC`)
	if err != nil {
		return fmt.Errorf("querying subscriptions: %w", err)
	}
	defer rows.Close()

	now := time.Now()
	out := []renewalRow{}
	var total float64
	for rows.Next() {
		var r renewalRow
		if err := rows.Scan(&r.Plan, &r.Status, &r.Price, &r.PeriodEnd); err != nil {
			return fmt.Errorf("scanning subscription: %w", err)
		}
		end := parseFlexibleTime(r.PeriodEnd)
		if end.IsZero() || end.Before(now) {
			continue // only forward-looking renewals
		}
		days := int(end.Sub(now).Hours() / 24)
		r.WeeksOut = days / 7
		r.Bucket = fmt.Sprintf("week +%d", r.WeeksOut)
		total += r.Price
		out = append(out, r)
	}
	if err := rows.Err(); err != nil {
		return err
	}
	fmt.Fprintf(cmd.ErrOrStderr(), "renewals: %d upcoming renewals, %.2f total forecast cost\n", len(out), total)
	return printJSONFiltered(cmd.OutOrStdout(), out, flags)
}

type costEfficiencyResult struct {
	MonthlySpend       float64 `json:"monthlySpend"`
	AssignedMailboxes  int     `json:"assignedMailboxes"`
	PurchasedMailboxes int     `json:"purchasedMailboxes"`
	CostPerAssigned    float64 `json:"costPerAssignedMailbox"`
	CostPerPurchased   float64 `json:"costPerPurchasedMailbox"`
}

func analyticsCostEfficiency(cmd *cobra.Command, db *store.Store, flags *rootFlags) error {
	if !hintIfUnsynced(cmd, db, "subscriptions") {
		hintIfStale(cmd, db, "subscriptions", flags.maxAge)
	}
	var spend float64
	if err := db.DB().QueryRowContext(cmd.Context(),
		`SELECT COALESCE(SUM(price),0) FROM "subscriptions" WHERE UPPER(COALESCE(subscription_status,'')) = 'ACTIVE'`).Scan(&spend); err != nil {
		return fmt.Errorf("summing subscription spend: %w", err)
	}
	purchased, assigned := resolveMailboxCounts(cmd, db, flags)
	res := costEfficiencyResult{
		MonthlySpend:       spend,
		AssignedMailboxes:  assigned,
		PurchasedMailboxes: purchased,
	}
	if assigned > 0 {
		res.CostPerAssigned = round2(spend / float64(assigned))
	}
	if purchased > 0 {
		res.CostPerPurchased = round2(spend / float64(purchased))
	}
	fmt.Fprintf(cmd.ErrOrStderr(), "cost-efficiency: %.2f active spend / %d assigned mailboxes\n", spend, assigned)
	return printJSONFiltered(cmd.OutOrStdout(), res, flags)
}

type capacityResult struct {
	PurchasedMailboxes int `json:"purchasedMailboxes"`
	AssignedMailboxes  int `json:"assignedMailboxes"`
	AvailableMailboxes int `json:"availableMailboxes"`
}

func analyticsCapacity(cmd *cobra.Command, db *store.Store, flags *rootFlags) error {
	purchased, assigned := resolveMailboxCounts(cmd, db, flags)
	available := purchased - assigned
	if available < 0 {
		available = 0
	}
	res := capacityResult{
		PurchasedMailboxes: purchased,
		AssignedMailboxes:  assigned,
		AvailableMailboxes: available,
	}
	fmt.Fprintf(cmd.ErrOrStderr(), "capacity: %d purchased, %d assigned, %d available\n", purchased, assigned, available)
	return printJSONFiltered(cmd.OutOrStdout(), res, flags)
}

// resolveMailboxCounts returns the authenticated account's purchased and
// assigned mailbox counts. It prefers a live /v2/users call (authoritative,
// always current) and falls back to the synced user table when the API is
// unreachable, so capacity and cost-efficiency stay correct even when sync did
// not populate the user row.
func resolveMailboxCounts(cmd *cobra.Command, db *store.Store, flags *rootFlags) (purchased, assigned int) {
	if c, err := flags.newClient(); err == nil {
		if raw, err := c.Get(cmd.Context(), "/v2/users", nil); err == nil {
			var env struct {
				Data struct {
					PurchasedMailboxes int `json:"purchasedMailboxes"`
					AssignedMailboxes  int `json:"assignedMailboxes"`
				} `json:"data"`
			}
			if json.Unmarshal(raw, &env) == nil && (env.Data.PurchasedMailboxes > 0 || env.Data.AssignedMailboxes > 0) {
				return env.Data.PurchasedMailboxes, env.Data.AssignedMailboxes
			}
		}
	}
	_ = db.DB().QueryRowContext(cmd.Context(),
		`SELECT COALESCE(MAX(purchased_mailboxes),0), COALESCE(MAX(assigned_mailboxes),0) FROM "user"`).Scan(&purchased, &assigned)
	return purchased, assigned
}

// parseFlexibleTime parses the common timestamp shapes Zapmail returns
// (RFC3339, date-only). Returns the zero time on failure.
func parseFlexibleTime(s string) time.Time {
	s = strings.TrimSpace(s)
	if s == "" {
		return time.Time{}
	}
	layouts := []string{time.RFC3339, "2006-01-02T15:04:05.000Z", "2006-01-02T15:04:05Z", "2006-01-02"}
	for _, l := range layouts {
		if t, err := time.Parse(l, s); err == nil {
			return t
		}
	}
	return time.Time{}
}

func round2(f float64) float64 {
	return float64(int64(f*100+0.5)) / 100
}
